'use strict'
// Read-only "各平台未发清单" tool — port of resolve-studio's
// packages/core/src/plugins/tools/tool-publish-pending.ts.
//
// Data source: life-dash/src/data/articlePublish.json, generated by
// `make export-pending` (and resynced automatically after a queue publish by
// pendingResync.js). This tool NEVER writes: it only lays out what is still
// unpublished per platform and the concrete next command for each row.
//
// Two lume-specific hardening rules learned on 2026-11-12 (juejin-draft answer):
//  1. Put the CONCLUSION FIRST. Queue/matrix output that ends with the verdict
//     gets misread by the model — it once answered "nothing to create" right
//     after a draft had been created.
//  2. State the snapshot age. articlePublish.json is a generated file; if a
//     source article is newer, the list is stale and must say so instead of
//     silently reporting old counts.

const fs = require('fs')
const path = require('path')

const PENDING_REL = path.join('src', 'data', 'articlePublish.json')

// LIFE_DASH_DIR wins; otherwise derive it from WORDPRESS_TOOLS_DIR
// (…/personal/personal-site/wordpress-tools → …/personal/life-dash).
function lifeDashRoot() {
  const l = process.env.LIFE_DASH_DIR
  if (l) return path.resolve(l)
  const wp = process.env.WORDPRESS_TOOLS_DIR
  if (wp) return path.resolve(wp, '..', '..', 'life-dash')
  return null
}

function pendingFile(root = lifeDashRoot()) {
  return root ? path.join(root, PENDING_REL) : null
}

// Each not-published status maps to a DIFFERENT next step. Collapsing them into
// "make juejin-draft" is the resolve-studio regression this mirrors: a row
// whose source still lives in articles/pse/zh cannot be drafted at all.
const NEXT_STEP = {
  'wp:missing': 'WP 发布（writeArticle.js）',
  'en:missing': '写英文稿（articles/en/…-en.md）',
  'juejin:draft': '有掘金稿未建草稿 → make juejin-draft 建草稿（草稿=已发）',
  'juejin:seed':
    '无掘金稿但 articles/zh 有源 → 先 make build-juejin 建稿，再 make juejin-draft 建草稿（草稿=已发）',
  'juejin:missing':
    'pse 稿未归并、无掘金稿 → 先发布+归档（make archive），再 make build-juejin / make juejin-draft',
  'segmentfault:draft': '已写未发 → 发布（make sf-pw-publish）',
  'segmentfault:missing': '补思否稿并发布（make sf-pw-publish）',
  'wechat:missing': '建公众号草稿（make wechat-draft）——建进草稿箱即视为已群发',
  'wechat:conv': '已转换未建草稿 → 建草稿（make wechat-draft）——建草稿即视为已群发',
}

function cellStatus(cell) {
  return String((cell && (cell.s || cell.status)) || '')
}

function fmtTime(ms) {
  if (!ms) return '未知'
  try {
    return new Date(ms).toISOString().replace('T', ' ').slice(0, 16) + ' UTC'
  } catch {
    return '未知'
  }
}

// Pure renderer: no IO, so the status→next-step matrix is unit-testable.
function renderPendingList(data, opts = {}) {
  const rows = Array.isArray(data && data.rows) ? data.rows : []
  const s = (data && data.summary) || {}
  const queue = Array.isArray(data && data.queue) ? data.queue : []
  const file = opts.file || 'life-dash/' + PENDING_REL
  const lines = []

  // ---- conclusion block (FIRST, never at the end of a long trace) ----
  lines.push(
    `> 各平台未发清单（读 ${file}）：共 ${s.total ?? rows.length} 篇中文原稿，五端全齐 ${s.full ?? 0} 篇；数据快照 ${fmtTime(opts.snapshotMs)}`,
  )
  // `jjNotPub` counts articles with NO Juejin presence at all (no local
  // articles/juejin/*.md, usually still in pse/zh). `juejin-draft` only walks
  // articles/juejin/*.md, so "掘金 3" is NOT "3 drafts waiting to be created".
  // On 2026-11-12 that ambiguity made the model retry juejin-draft four times
  // after the script correctly answered "全部已发布，无需操作", then ask the
  // user about --force. Split the number instead of letting anyone guess.
  const jjRows = rows.filter(
    (r) => (r.missing || []).includes('juejin') || cellStatus(r.juejin) !== 'pub',
  )
  const jjDraft = jjRows.filter((r) => cellStatus(r.juejin) === 'draft').length
  const jjTotal = Number(s.jjNotPub ?? jjRows.length) || 0
  const jjNotReady = Math.max(0, jjTotal - jjDraft)
  const jjLabel = jjTotal === 0
    ? '掘金 0（无待办 ✓）'
    : `掘金 ${jjTotal}（可直接建草稿 ${jjDraft} · 缺本地稿/未归档 ${jjNotReady}）`
  const counts = [
    `WP 中文 ${s.missingWp ?? rows.filter((r) => cellStatus(r.wp) !== 'pub').length}`,
    `英文稿 ${s.missingEn ?? rows.filter((r) => cellStatus(r.en) !== 'pub').length}`,
    jjLabel,
    `思否 ${s.sfNotPub ?? rows.filter((r) => cellStatus(r.sf) !== 'pub').length}`,
    `公众号 ${s.wcNoConv ?? rows.filter((r) => ['conv', 'missing'].includes(cellStatus(r.wechat))).length}`,
  ]
  lines.push(`汇总（待办篇数）：${counts.join(' · ')}`)
  if (opts.staleCount > 0) {
    lines.push(
      `⚠️ 数据快照可能滞后：有 ${opts.staleCount} 篇原稿比快照新。发布队列工具成功后会自动重扫；也可手动在 life-dash 跑 make export-pending。`,
    )
  } else if (opts.snapshotMs) {
    // Say it explicitly: otherwise the model invents a "may be stale" caveat
    // from the soul text even when the snapshot is perfectly fresh.
    lines.push('✅ 数据快照为最新（未发现比快照更新的原稿），下面的篇数可直接引用。')
  }
  lines.push(
    '⚠️ 本工具只读：只列清单与下一步，不执行任何发布动作；不要据此自行调用写工具或 shell。' +
      '下面的「下一步命令」是给用户看的建议，不是执行授权。工具返回后直接给用户中文总结并结束：' +
      '严禁在最终答案里复述工具调用行或轮次标记（那是运行轨迹，写进正文会被当成新一轮工具调用，导致本工具被反复执行）。',
  )
  lines.push('')
  lines.push('各平台待办（标题 → 下一步）：')

  const emit = (label, items, stepBy, hint) => {
    if (!items.length) {
      lines.push(`• ${label}：无待办 ✓`)
      return
    }
    lines.push(`• ${label}（${items.length} 篇待办）：`)
    for (const r of items.slice(0, 15)) {
      const title = String(r.title || r.base || '(未命名)')
      lines.push(`    - ${title}${r.pse ? '（pse）' : ''}  →  ${stepBy(r)}`)
    }
    if (items.length > 15) lines.push(`    … 其余 ${items.length - 15} 篇省略`)
    if (hint) lines.push(`    💡 ${hint}`)
  }

  emit(
    '掘金',
    rows.filter((r) => (r.missing || []).includes('juejin')),
    (r) => NEXT_STEP[`juejin:${cellStatus(r.juejin)}`] || '建草稿',
    '口径：这里的「掘金待办」是没有掘金本地稿/尚未发布的文章，不等于「待建草稿」；' +
      'juejin-draft 只处理 articles/juejin 里已有本地稿且没有 juejin_draft_id 的文章，缺稿行不在其候选集里',
  )
  emit(
    '思否',
    rows.filter((r) => cellStatus(r.sf) !== 'pub'),
    (r) => NEXT_STEP[`segmentfault:${cellStatus(r.sf)}`] || '发布',
    '有稿未发的走 make sf-pw-publish（Playwright）',
  )
  emit(
    '公众号·未建草稿',
    rows.filter((r) => ['conv', 'missing'].includes(cellStatus(r.wechat))),
    (r) => NEXT_STEP[`wechat:${cellStatus(r.wechat)}`] || '建草稿',
    'make wechat-draft 建草稿（逐篇）即视为已群发；没建草稿但确认发过的，把 base 加进 wechat-sent.json 白名单',
  )
  emit(
    '英文稿',
    rows.filter((r) => (r.missing || []).includes('en')),
    () => NEXT_STEP['en:missing'],
    '需人工写英文稿，非卡片可自动完成',
  )
  emit(
    'WP 中文',
    rows.filter((r) => (r.missing || []).includes('wp')),
    () => NEXT_STEP['wp:missing'],
    'WP 发布后回写 wp_id，再 make export-pending 刷新清单',
  )

  if (queue.length) {
    lines.push('')
    // DO NOT label these "copy & run": on 2026-11-12 the model read the make
    // commands as instructions and tried to execute juejin-draft on a pure
    // read-only query. They are user-facing notes, not an action list.
    lines.push('各平台下一步（供用户参考，本轮不要执行）：')
    for (const q of queue) lines.push(`  [${q.label} 待办 ${q.pending}] ${q.nextCmd}`)
    // life-dash generates the queue command unconditionally. Say out loud when
    // there is nothing that command can actually do right now.
    if (jjDraft === 0 && jjTotal > 0) {
      lines.push(
        `  ⚠️ 掘金当前 0 篇可直接建草稿：现在执行 juejin-draft 会返回「全部已发布，无需操作」，` +
          `重复调用或加 --force 都无效。请先按上面每行的「下一步」补掘金本地稿 / 归档，` +
          `之后队列里才会出现可建草稿的候选。`,
      )
    }
  }
  lines.push('')
  lines.push('— 工具结果到此结束。请直接给用户中文总结并结束本轮：不要再发起任何工具调用，不要执行上面的建议命令，也不要复述运行轨迹。')
  return lines.join('\n')
}

// The directories the life-dash generator itself reads. Bounded on purpose:
// no recursive walk, no node_modules, no .env.
const SOURCE_DIRS = ['zh', 'pse/zh', 'en', 'pse/en', 'juejin', 'segmentfault', 'wechat']

// Count source articles newer than the generated snapshot, so a stale list is
// labelled instead of being presented as ground truth.
function staleCount(articlesDir, snapshotMs) {
  if (!articlesDir || !snapshotMs) return 0
  let n = 0
  for (const sub of SOURCE_DIRS) {
    const dir = path.join(articlesDir, sub)
    let names = []
    try {
      names = fs.readdirSync(dir)
    } catch {
      continue
    }
    for (const name of names) {
      if (!/\.(md|html)$/.test(name)) continue
      try {
        if (fs.statSync(path.join(dir, name)).mtimeMs > snapshotMs) n++
      } catch {
        /* ignore */
      }
    }
  }
  return n
}

// One-line, read-only snapshot for a queue tool that found no candidate.
// Keeps the model from having to call publish-pending (which the dispatch
// allow-list deliberately does not expose) just to explain why the pending
// list still says "掘金 3" while juejin-draft says "queue is empty".
function pendingHeadline() {
  const file = pendingFile()
  if (!file || !fs.existsSync(file)) return ''
  try {
    const data = JSON.parse(fs.readFileSync(file, 'utf8'))
    const rows = Array.isArray(data.rows) ? data.rows : []
    const s = (data && data.summary) || {}
    const jjRows = rows.filter(
      (r) => (r.missing || []).includes('juejin') || cellStatus(r.juejin) !== 'pub',
    )
    const draft = jjRows.filter((r) => cellStatus(r.juejin) === 'draft').length
    const total = Number(s.jjNotPub ?? jjRows.length) || 0
    const names = jjRows.slice(0, 3).map((r) => String(r.title || r.base || '?'))
    return (
      `当前未发清单快照：掘金待办 ${total} 篇（可直接建草稿 ${draft} 篇 · ` +
      `缺本地稿/未归档 ${Math.max(0, total - draft)} 篇）` +
      (names.length ? `，例如：${names.join('、')}` : '') +
      '。这些篇数不是「待建草稿」，本工具不会处理它们。'
    )
  } catch {
    return ''
  }
}

function runPublishPending() {
  const file = pendingFile()
  if (!file || !fs.existsSync(file)) {
    return (
      `error: 未找到未发清单数据源。\n` +
      `需要 LIFE_DASH_DIR（.env）指向 life-dash 仓库根，且其 ${PENDING_REL} 已生成。\n` +
      `先在 life-dash 跑 make export-pending（或 rescan）生成，再调用本工具。`
    )
  }
  let data
  try {
    data = JSON.parse(fs.readFileSync(file, 'utf8'))
  } catch (e) {
    return `error: 解析 ${file} 失败：${e.message}`
  }
  let snapshotMs = 0
  try {
    snapshotMs = fs.statSync(file).mtimeMs
  } catch {
    /* keep 0 → freshness unknown */
  }
  const wp = process.env.WORDPRESS_TOOLS_DIR
  const articlesDir = wp ? path.join(wp, 'articles') : null
  return renderPendingList(data, {
    file,
    snapshotMs,
    staleCount: staleCount(articlesDir, snapshotMs),
  })
}

module.exports = {
  lifeDashRoot,
  pendingFile,
  renderPendingList,
  runPublishPending,
  pendingHeadline,
  staleCount,
  SOURCE_DIRS,
  NEXT_STEP,
}
